":"Service","name":"Homeowner Claim Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/home-insurance-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Condo, HOA & Commercial Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/condo-hoa-commercial-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm & Tornado Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/tree-impact-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Rain Intrusion Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/water-rain-intrusion-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/house-fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire & Ash Claim Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/wildfire-ash-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow, Ice Dam & Freeze Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/snow-ice-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Windstorm damage","Wildfire claims","Xactimate estimating"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://washingtoninsuranceappraiser.com/#website","url":"https://washingtoninsuranceappraiser.com/","name":"Washington Insurance Appraiser","publisher":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/#webpage","url":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/","name":"Insurance Appraisal FAQ | Washington Costs, Timing & Rules","description":"Answers to common Washington insurance appraisal questions: how it works, what it costs, timing, OIC and IFCA basics, and when awards bind.","inLanguage":"en-US","isPartOf":{"@id":"https://washingtoninsuranceappraiser.com/#website"},"about":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"publisher":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"dateModified":"2026-11-14","breadcrumb":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/#breadcrumb"},"primaryImageOfPage":{"@type":"ImageObject","@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/#primaryimage","url":"https://washingtoninsuranceappraiser.com/assets/img/photos/living-room.webp","width":1200,"height":800,"caption":"Living room with a stone fireplace, leather sectional sofa and hardwood floors"},"mainEntity":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://washingtoninsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal FAQ","item":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/"}],"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"It is a process written into most property policies for settling disagreements about the amount of a covered loss. Each side names an appraiser, the appraisers choose an umpire, and an award signed by two of the three sets the amount."}},{"@type":"Question","name":"Is appraisal the same as arbitration?","acceptedAnswer":{"@type":"Answer","text":"They’re similar but not the same. Appraisal is narrower: it decides the amount of loss, not legal questions or coverage. It’s usually less formal and faster."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Either you or the insurer, as long as the policy has an appraisal clause and the disagreement is about the amount of loss."}},{"@type":"Question","name":"Is the award binding?","acceptedAnswer":{"@type":"Answer","text":"On the amount of loss, yes, once two of the three panel members sign. Courts can set awards aside in limited circumstances, such as fraud or a panel exceeding its authority."}},{"@type":"Question","name":"Does appraisal decide coverage?","acceptedAnswer":{"@type":"Answer","text":"No. If the insurer says something isn’t covered, that is a coverage dispute. Appraisal can value the damage, but whether it is payable may still be argued."}},{"@type":"Question","name":"How much does appraisal cost?","acceptedAnswer":{"@type":"Answer","text":"Each side pays its own appraiser and usually half the umpire’s fee. Appraiser fees may be flat, hourly or a percentage of the increase. Get any arrangement in writing before work starts."}},{"@type":"Question","name":"How long does it take?","acceptedAnswer":{"@type":"Answer","text":"Straightforward home claims often finish in six to twelve weeks after both appraisers are named. Commercial and total-loss claims take longer."}},{"@type":"Question","name":"When is a gap too small for appraisal?","acceptedAnswer":{"@type":"Answer","text":"As a rough guide, if the difference is under about 10% of the insurer’s estimate or a few thousand dollars, a documented supplement request may be more cost-effective. Our appraisal payoff calculator can help you check."}},{"@type":"Question","name":"Does appraisal stop the suit-limitation deadline?","acceptedAnswer":{"@type":"Answer","text":"Not automatically. Washington law does not let policies shorten the time to sue to less than one year from the loss, and many homeowner policies use exactly one year. Protect that deadline separately and talk to an attorney if it’s close."}},{"@type":"Question","name":"Who regulates insurers in Washington?","acceptedAnswer":{"@type":"Answer","text":"The Office of the Insurance Commissioner (OIC), based in Tumwater. It licenses insurers and adjusters, enforces claims-handling rules and takes consumer complaints."}},{"@type":"Question","name":"What is the Insurance Fair Conduct Act?","acceptedAnswer":{"@type":"Answer","text":"IFCA is a Washington law that gives policyholders a legal remedy when an insurer unreasonably denies coverage or payment of benefits. It has notice requirements before suit. It is a legal claim, separate from appraisal, so ask a Washington attorney about it."}},{"@type":"Question","name":"Does Washington have a FAIR plan or wind pool?","acceptedAnswer":{"@type":"Answer","text":"Washington does not currently operate a state FAIR plan or windstorm pool like some coastal states. Homeowners who can’t find standard coverage often turn to the surplus lines market. Lawmakers and the OIC have discussed options as wildfire risk grows."}},{"@type":"Question","name":"Is earthquake covered?","acceptedAnswer":{"@type":"Answer","text":"Not under standard homeowner policies. Earthquake coverage is sold separately or by endorsement, usually with a percentage deductible such as 10% to 20% of the dwelling limit."}},{"@type":"Question","name":"Is flood covered?","acceptedAnswer":{"@type":"Answer","text":"Not under standard homeowner policies. Flood from rising water requires separate flood insurance, such as through the National Flood Insurance Program."}},{"@type":"Question","name":"Are you a public adjuster or a law firm?","acceptedAnswer":{"@type":"Answer","text":"Neither. We provide appraisal, estimate review and umpire services. We don’t negotiate claims outside the appraisal process and we don’t give legal advice."}},{"@type":"Question","name":"Do you serve the whole state?","acceptedAnswer":{"@type":"Answer","text":"Yes. We work in all 39 Washington counties, from Puget Sound and the coast to the Columbia Basin and the Inland Northwest."}},{"@type":"Question","name":"What should I send for a first review?","acceptedAnswer":{"@type":"Answer","text":"The insurer’s full estimate, your declarations page, any contractor estimate, photos and the most important letters or emails from the insurer."}},{"@type":"Question","name":"Can I hire you after the insurer has already demanded appraisal?","acceptedAnswer":{"@type":"Answer","text":"Yes. We can step in as your appraiser at any point after a demand, as long as the policy’s deadlines are met."}}],"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-faq/#faq"}]}</script>
</head>
